quests[43888] = { id = 43888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es steht geschrieben", description = "Ihr kämpft mit uraltem Stahl, der durch Magien gestärkt ist, die wir kaum verstehen.\n\nWenn Ihr wirklich das Potenzial Eurer Waffen freisetzen wollt, müsst Ihr mehr davon verstehen, wie sie geschmiedet wurden und welche Kämpfe sie bestritten haben. Dabei kann ich Euch helfen.\n\nWelche Ressourcen Ihr auch immer für diese Nachforschungen aufbringen könnt – ich verspreche Euch, es wird sich lohnen.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Ich werde bald Ergebnisse für Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[43889] = { id = 43889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Gewölbe", description = "Die Nachtfestung zu infiltrieren und einzunehmen, wird eine echte Herausforderung. Selbst ihre Katakomben und Gewölbe sind vermutlich streng bewacht, aber wir müssen auf jeden Fall einen Weg hinein finden.", sourceObjective = "Tötet Trilliax in der Nachtfestung.", progress = "Wie gestalten sich die Herausforderungen in der Nachtfestung?", completion = "Habt Ihr die Nachtfestung bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43890] = { id = 43890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Gewölbe", description = "Die Nachtfestung zu infiltrieren und einzunehmen, wird eine echte Herausforderung. Selbst ihre Katakomben und Gewölbe sind vermutlich streng bewacht, aber wir müssen auf jeden Fall einen Weg hinein finden.", sourceObjective = "Tötet Trilliax in der Nachtfestung.", progress = "Wie gestalten sich die Herausforderungen in der Nachtfestung?", completion = "Habt Ihr die Nachtfestung bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43891] = { id = 43891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Gewölbe", description = "Die Nachtfestung zu infiltrieren und einzunehmen, wird eine echte Herausforderung. Selbst ihre Katakomben und Gewölbe sind vermutlich streng bewacht, aber wir müssen auf jeden Fall einen Weg hinein finden.", sourceObjective = "Tötet Trilliax in der Nachtfestung.", progress = "Wie gestalten sich die Herausforderungen in der Nachtfestung?", completion = "Habt Ihr die Nachtfestung bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43892] = { id = 43892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Ordensressourcen", progress = "Diese Siegel gewähren Euch eine zusätzliche Chance auf Schätze in Dungeons und Schlachtzügen, aber um welchen Preis? Euer Orden wird diese Ressourcen bestimmt nicht vermissen, aber ich frage Euch: Wo soll das enden? Werdet Ihr jemals aufhören, das Leben anderer zur Befriedigung Eurer Gier zu riskieren?\n\nIhr könnt höchstens drei Siegel pro Woche erhalten. Das hier zählt als eins der drei. Nächste Woche habe ich andere Siegel.", completion = "Fühlt Ihr Euch sicher, Fremder?" }
quests[43893] = { id = 43893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Gehamsterte Ordensressourcen", progress = "Doppelt so teuer wie das letzte, aber vielleicht ist es den Preis ja wert. Oder wäre eine andere Währung vielleicht einfacher für Euch? Ihr habt die Wahl.\n\nVergesst nicht, dass Ihr höchstens drei Siegel pro Woche erhalten könnt. Das hier zählt als eins der drei. Nächste Woche habe ich andere Siegel.", completion = "Fühlt Ihr Euch sicher, Fremder?" }
quests[43894] = { id = 43894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Überschüssige Ordensressourcen", progress = "Viermal so teuer wie das erste, aber nur für ein Siegel. Denkt dran, dass ich auch effizientere Optionen anbiete, obwohl ich niemals jemanden ablehne, der darauf besteht, mir mehr zu geben. Ihr habt die Wahl.\n\nVergesst nicht, dass Ihr höchstens drei Siegel pro Woche erhalten könnt. Das hier zählt als eins der drei. Nächste Woche habe ich andere Siegel.", completion = "Fühlt Ihr Euch sicher, Fremder?" }
quests[43895] = { id = 43895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Gold", progress = "Diese Siegel gewähren Euch eine zusätzliche Chance auf Schätze in Dungeons und Schlachtzügen, aber um welchen Preis? Gold ist in der Tat ein Schatz, aber zusätzliche Schätze für Gold? Das ist das Angebot, das ich Euch unterbreite.\n\nDenkt daran, Ihr könnt pro Woche nur drei Siegel erwerben. Dieses hier zählt dazu. Nächste Woche habe ich andere im Angebot.", completion = "Ein einfacher Austausch mit vielschichtigen Ergebnissen. Das ist die Kunst des Geschäftemachens." }
quests[43896] = { id = 43896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Haufen von Goldmünzen", progress = "Doppelt so teuer wie das letzte, aber vielleicht ist es den Preis ja wert. Oder wäre eine andere Währung vielleicht einfacher für Euch? Ihr habt die Wahl.\n\nVergesst nicht, dass Ihr höchstens drei Siegel pro Woche erhalten könnt. Das hier zählt als eins der drei. Nächste Woche habe ich andere Siegel.", completion = "Ein einfacher Austausch mit vielschichtigen Ergebnissen. Das ist die Kunst des Geschäftemachens." }
quests[43897] = { id = 43897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Immenses Vermögen in Gold", progress = "Viermal so teuer wie das erste, aber nur für ein Siegel. Denkt dran, dass ich auch effizientere Optionen anbiete, obwohl ich niemals jemanden ablehne, der darauf besteht, mir mehr zu geben. Ihr habt die Wahl.\n\nVergesst nicht, dass Ihr höchstens drei Siegel pro Woche erhalten könnt. Das hier zählt als eins der drei. Nächste Woche habe ich andere Siegel.", completion = "Ein einfacher Austausch mit vielschichtigen Ergebnissen. Das ist die Kunst des Geschäftemachens." }
quests[43898] = { id = 43898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit für den ersten Schritt", description = "Dank Eurer unermüdlichen Anstrengungen kann sich das Herz von Zin-Azshari nun gegen die geballte Macht der Legion behaupten.\n\nDas Ziel unserer langen Reise hat seit dem ersten Schritt einen dunklen Schatten auf uns geworfen, die Nachtfestung, nun eine Bastion von Gul'dan höchstpersönlich.\n\nAber bevor wir uns der Festung zuwenden, sollten wir unsere Kräfte wieder mit der Mondwache in Shal'Aran vereinen. Wir sind weiterhin auf ihre Fähigkeiten angewiesen, und sie haben wohl auch noch eine Rechnung mit ihren ehemaligen Brüdern und Schwestern zu begleichen.", sourceObjective = "Trefft Erzmagier Kalec in Shal'Aran.", completion = "Wir haben einen rückseitigen Eingang in die Nachtfestung gefunden, der den Armeen am Vordereingang etwas Erleichterung verschaffen könnte.\n\nMit Betonung auf \"etwas\".", sourceObjectiveStatus = "unverified-source-field" }
quests[43899] = { id = 43899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rösser der Verdammten", description = "Salanar der Reiter ist gerade aus dem Schattenreich in der Schwarzen Festung eingetroffen. Er allein verfügt über das Wissen und die Macht, die Rösser der Vier Reiter zu beschwören.\n\nSalanar hat uns eine Liste der Dinge gegeben, die er für die Rösser benötigt. Ich habe daher eine Reihe von Missionen zusammengestellt, um diese Gegenstände zu besorgen.\n\nÜber den Missionstisch könnt Ihr die Aufgaben Euren bevorzugten Champions zuweisen.", sourceObjective = "Schließt 5 Missionen der Reihe \"Gefallene Rösser\" ab.", completion = "Hervorragend, Todesgebieter. Die Missionen um die Rösser der Verdammten waren ein voller Erfolg. Salanar der Reiter hat nun den ersten Satz an benötigten Gegenständen, um die Rösser zu beschwören.", sourceObjectiveStatus = "unverified-source-field" }
quests[43900] = { id = 43900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: All - Troop A Enabled" }
