quests[43902] = { id = 43902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Der Fall von Cenarius", description = "Wir wissen zwar, dass der Alptraum die Grenzen zwischen Realität und Traum verschwimmen lässt, aber die Bedrohung ist für uns ganz real. Unsere eigenen Verbündeten sind der Dunkelheit verfallen.", sourceObjective = "Besiegt Cenarius im Smaragdgrünen Alptraum.", progress = "Wie gestalten sich die Herausforderungen im Smaragdgrünen Alptraum?", completion = "Habt Ihr den Smaragdgrünen Alptraum bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43903] = { id = 43903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Xavius", description = "Die Zeit ist gekommen, gegen die Ursache des Alptraums vorzugehen und das Gleichgewicht im Smaragdgrünen Traum wiederherzustellen. Kämpft Euch in das Herz des Alptraums vor und stellt Euch dem Alptraumfürsten Xavius.", sourceObjective = "Besiegt Xavius im Smaragdgrünen Alptraum.", progress = "Wie gestalten sich die Herausforderungen im Smaragdgrünen Alptraum?", completion = "Habt Ihr den Smaragdgrünen Alptraum bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
