quests[43910] = { id = 43910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Hochbotaniker Tel'arn", description = "Die Nachtgeborenen sind in vielen Formen der Magie bewandert, und wir werden in der Nachtfestung wahrscheinlich auf viele starke Gegner treffen. Ihre mächtigsten Magier und Krieger müssen fallen, bevor wir Gul'dan stellen können.", sourceObjective = "Tötet Hochbotaniker Tel'arn in der Nachtfestung.", progress = "Wie gestalten sich die Herausforderungen in der Nachtfestung?", completion = "Habt Ihr die Nachtfestung bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43911] = { id = 43911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Elisande", description = "Vor langer Zeit stellte sich Großmagistrix Elisande gegen die Legion und wies Königin Azshara selbst zurück. Im Laufe der Jahrtausende hat Elisande ihre Meinung geändert, und nun ist sie eine Verbündete der Dämonen. Es wird Zeit, ihr die Stirn zu bieten.", sourceObjective = "Tötet Elisande in der Nachtfestung.", progress = "Wie gestalten sich die Herausforderungen in der Nachtfestung?", completion = "Habt Ihr die Nachtfestung bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43912] = { id = 43912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Gul'dan", description = "Gul'dan war der Ansicht, die Legion wäre das einzig wahre Schicksal der Orcs, und hat unermüdlich sein brutales Vorhaben vorangetrieben. Nun ist endlich der Tag gekommen, dass wir seinem dämonischen Kreuzzug ein Ende setzen und endgültig für Gerechtigkeit sorgen.", sourceObjective = "Tötet Gul'dan in der Nachtfestung.", progress = "Wie gestalten sich die Herausforderungen in der Nachtfestung?", completion = "Habt Ihr die Nachtfestung bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43913] = { id = 43913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Hochbotaniker Tel'arn", description = "Die Nachtgeborenen sind in vielen Formen der Magie bewandert, und wir werden in der Nachtfestung wahrscheinlich auf viele starke Gegner treffen. Ihre mächtigsten Magier und Krieger müssen fallen, bevor wir Gul'dan stellen können.", sourceObjective = "Tötet Hochbotaniker Tel'arn in der Nachtfestung.", progress = "Wie gestalten sich die Herausforderungen in der Nachtfestung?", completion = "Habt Ihr die Nachtfestung bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43914] = { id = 43914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Elisande", description = "Vor langer Zeit stellte sich Großmagistrix Elisande gegen die Legion und wies Königin Azshara selbst zurück. Im Laufe der Jahrtausende hat Elisande ihre Meinung geändert, und nun ist sie eine Verbündete der Dämonen. Es wird Zeit, ihr die Stirn zu bieten.", sourceObjective = "Tötet Elisande in der Nachtfestung.", progress = "Wie gestalten sich die Herausforderungen in der Nachtfestung?", completion = "Habt Ihr die Nachtfestung bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43915] = { id = 43915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Gul'dan", description = "Gul'dan war der Ansicht, die Legion wäre das einzig wahre Schicksal der Orcs, und hat unermüdlich sein brutales Vorhaben vorangetrieben. Nun ist endlich der Tag gekommen, dass wir seinem dämonischen Kreuzzug ein Ende setzen und endgültig für Gerechtigkeit sorgen.", sourceObjective = "Tötet Gul'dan in der Nachtfestung.", progress = "Wie gestalten sich die Herausforderungen in der Nachtfestung?", completion = "Habt Ihr die Nachtfestung bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[43916] = { id = 43916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Hochbotaniker Tel'arn", description = "Die Nachtgeborenen sind in vielen Formen der Magie bewandert, und wir werden in der Nachtfestung wahrscheinlich auf viele starke Gegner treffen. Ihre mächtigsten Magier und Krieger müssen fallen, bevor wir Gul'dan stellen können.", sourceObjective = "Tötet Hochbotaniker Tel'arn in der Nachtfestung.", progress = "Wie gestalten sich die Herausforderungen in der Nachtfestung?", completion = "Habt Ihr die Nachtfestung bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
