quests[43923] = { id = 43923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sternlichtrose", progress = "Habt Ihr uns Vorräte mitgebracht?", completion = "Gut gemacht, {name}.\n\nDiese Vorräte sind absolut unverzichtbar, um die Elixiere für die kommende Schlacht zu brauen." }
quests[43924] = { id = 43924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyblut", progress = "Habt Ihr uns Vorräte mitgebracht?", completion = "Gut gemacht, {name}.\n\nDiese Vorräte sind absolut unverzichtbar, um die Elixiere für die kommende Schlacht zu brauen." }
quests[43925] = { id = 43925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenschuppenkoi", progress = "Habt Ihr uns Vorräte mitgebracht?", completion = "Gut gemacht, {name}.\n\nDiese Vorräte sind absolut unverzichtbar, um die Elixiere für die kommende Schlacht zu brauen." }
quests[43926] = { id = 43926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion: Die Rückkehr der Legion", description = "Krieger der Horde, schleift Eure Äxte und schärft Eure Speere. Die Armeen der Brennenden Legion sind in diese Welt zurückgekehrt.\n\nWir laufen sofort aus der Messerbucht aus. Die ganze Macht der Horde wird die Legion wie ein Hammer treffen. Da kriegt sogar Sargeras Kopfschmerzen.\n\nAb auf die Schiffe, wir haben 'ne Menge Dämonenblut zu vergießen.", sourceObjective = "Meldet Euch bei Holgar Sturmaxt an der Blockade von Dranosh'ar.\n\nBereitgestellter Gegenstand:", completion = "Die Schiffe verlassen das Dock der Messerbucht.\n\nBereitet Euch gut vor, bevor Ihr die Reise antretet. Ich fürchte, dieser Kampf wird nicht einfach.", sourceObjectiveStatus = "unverified-source-field" }
quests[43928] = { id = 43928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anhäufungen der Qual", description = "Unsere Vorbereitungen für die Beschwörung der Rösser der Verdammten sind beinahe abgeschlossen.\n\nSalanar der Reiter hat uns eine Liste der verbleibenden Gegenstände gegeben. Für das Beschwörungsritual werden fünf unheilige Essenzen benötigt, die als Anhäufungen der Qual bekannt sind.\n\nIch selbst habe die notwendigen Missionen organisiert, um diese Gegenstände zu besorgen.\n\nÜber den Missionstisch könnt Ihr die Aufgaben Euren bevorzugten Champions zuweisen.", sourceObjective = "Schließt 5 Missionen der Reihe \"Unheilige Errungenschaften\" ab.", completion = "Da wir nun die Anhäufungen der Qual beschafft haben, ist unser Werk fast vollbracht. Bald werden sich die Rösser der Verdammten erheben... und die Brennende Legion wird fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[43929] = { id = 43929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vantusmeisterschaft" }
quests[43930] = { id = 43930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholde von Tel'anor" }
quests[43932] = { id = 43932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächte der Unterdrückung" }
quests[43933] = { id = 43933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Delas Mondfang", sourceObjective = "Hochlord, ich bin stolz, die ersten Schritte auf dieser neuen Reise tun.\n\nVielen Dank, dass Ihr mich unter Eure Fittiche genommen habt. Ich schwöre, dass ich den Prinzipien treu bleibe: Ich werde ehrenvoll handeln, stets für die gerechte Sache eintreten, Ungerechtigkeit an allen Orten bekämpfen und mit meinen neuen Brüdern und Schwestern der Silbernen Hand feiern.\n\nSchulter an Schulter stehen wir vereint im Lichte!", sourceObjectiveStatus = "unverified-source-field" }
quests[43934] = { id = 43934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Pfad", description = "Hochlord {name}, habt Ihr einen Moment Zeit?\n\nSeit Langem folge ich dem Pfad des Lichts und viele Jahre studierte ich bei den Mondpriesterinnen. Aber dennoch plagte mich stets das Gefühl, meine Ausbildung sei unvollständig. Ich wollte mehr.\n\nAls ich diese Hallen betrat, wurde mir klar, was mir gefehlt hatte. Ich glaube, dass ein neuer Pfad vor mir liegt.\n\nIch möchte ein Paladin der Silbernen Hand werden. Würdet Ihr mir gestatten, mich Euch anzuschließen?", sourceObjective = "Sprecht mit Delas Mondfang.", progress = "Was meint Ihr?", completion = "Vielen Dank, Hochlord.", sourceObjectiveStatus = "unverified-source-field" }
quests[43935] = { id = 43935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zweite Legende", description = "Vielleicht ist es an der Zeit, dass Ihr Eure Flexibilität hinsichtlich mächtiger Artefakte überdenkt. Ich denke, da gibt es noch andere, die es wert sind, herbeigeschafft zu werden, wenn Ihr interessiert seid.\n\nLasst mich Euch Eure Optionen aufzeigen. Dann könnt Ihr wählen.", sourceObjective = "Wählt ein zweites Artefakt, das Ihr suchen wollt.", completion = "Ausgezeichnet. Ihr könnt beginnen, sobald Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[43937] = { id = 43937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuflucht suchen", description = "Die Nachtsüchtigen in Suramar gehörten früher zu den Nachtgeborenen, doch ihre einstigen Brüder verbannten sie und verwehrten ihnen den Zugang zum Nachtbrunnen.\n\nIch glaube, sie könnten bei unserer Suche wertvolle Verbündete sein, wenn Ihr sie auf unsere Seite ziehen könnt. Ich weiß nur, dass sie irgendwo in Suramar untergetaucht sind.\n\nWenn Ihr die Nachtsüchtigen davon überzeugen könnt, uns zu helfen, könnten sie der Mondwache und uns womöglich Zuflucht direkt vor der Nase der Legion bieten.", sourceObjective = "Schließt den Handlungsstrang \"Einbruch der Nacht\" in Suramar ab und trefft dann Erzmagier Kalec in Shal'Aran.", sourceObjectiveStatus = "unverified-source-field" }
quests[43938] = { id = 43938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konzentration unserer Bemühungen", description = "Die Nachtsüchtigen in Suramar gehörten früher zu den Nachtgeborenen, doch ihre einstigen Brüder verbannten sie und verwehrten ihnen den Zugang zum Nachtbrunnen.\n\nIch glaube, sie könnten bei unserer Suche wertvolle Verbündete sein, wenn Ihr sie auf unsere Seite ziehen könnt. Ich weiß nur, dass sie irgendwo in Suramar untergetaucht sind.\n\nSucht anschließend die Mondwache in den nördlichen Lagen von Suramar auf. Auch sie könnte ein wertvoller Verbündeter für unsere Sache sein... wenn sie immer noch Gegner der Legion sind, wie vor vielen Jahren.", sourceObjective = "Schließt die Handlungsstränge \"Einbruch der Nacht\" und \"Die Mondwachenfestung\" in Suramar ab und trefft dann Erzmagier Kalec in Shal'Aran.", completion = "Sprechen wir mit Thalrenus, um unseren Schlachtplan zu erörtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[43939] = { id = 43939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Chosen" }
quests[43940] = { id = 43940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy Chosen" }
quests[43941] = { id = 43941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disc Chosen" }
quests[43942] = { id = 43942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwittertes Artefakt", description = "<Ihr habt ein seltsam aussehendes Artefakt der Naga bei dem Leichnam gefunden.\nAm Verwitterten Strand ist Euch Königin Mrgl-Mrgl aufgefallen. Vielleicht weiß sie ja, was es damit auf sich hat?>", sourceObjective = "Bringt das verwitterte Artefakt zu Königin Mrgl-Mrgl Mrgl Mrgl, die sich ganz in der Nähe aufhält.\n\nBereitgestellter Gegenstand:", completion = "Genau das habe ich gesucht! <Königin Mrgl-Mrgl studiert das Artefakt.> Ah! Ja. Aber an der Küste muss es noch mehr von diesen verwitterten Artefakten geben. Ich wäre Euch dankbar, wenn Ihr mir noch mehr bringen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[43943] = { id = 43943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung der Verdorrtenarmee" }
quests[43945] = { id = 43945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erweiterung des Horizonts", description = "Ihr lernt schnell, {class}t {name}. Die Elemente sprechen durch Euch. So eine Verbindung ist selten in der Welt.\n\nWahre Schamanen müssen viele Pfade beschreiten. Für jede Rolle braucht es die richtigen Werkzeuge. Nur mit den mächtigsten Waffen können wir die Legion besiegen. Vielleicht ist es an der Zeit, nach einer weiteren zu suchen?\n\nSprecht mit mir, damit wir die Optionen erörtern können.", sourceObjective = "Sprecht mit Aggra, um ein zweites Artefakt auszuwählen, das Ihr suchen wollt.", completion = "Also dann. Eure Verbündeten haben sich hier am Abgrund versammelt. Sie wissen am besten, wie es weitergehen soll.\n\nMögen Euch die Winde immer gewogen sein, Scharfseher.", sourceObjectiveStatus = "unverified-source-field" }
quests[43946] = { id = 43946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enhancement Chosen" }
quests[43947] = { id = 43947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Chosen" }
quests[43948] = { id = 43948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoration Chosen" }
quests[43949] = { id = 43949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr legendäre Waffen", description = "Es ist klug, mehr als nur eine Waffe mit in den Krieg zu nehmen. Manchmal ist die eine besser geeignet als die andere. Ihr solltet noch eine andere legendäre Waffe auswählen, die Ihr mitnehmen könnt, insbesondere gegen einen so tödlichen Feind.\n\nWas meint Ihr?", sourceObjective = "Wählt ein zweites Artefakt, das Ihr suchen wollt.", completion = "Eine mächtige Waffe für einen mächtigen Champion der Hallen. Lasst uns anfangen.", sourceObjectiveStatus = "unverified-source-field" }
