quests[43957] = { id = 43957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jade Darkhaven" }
quests[43958] = { id = 43958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echtes Beweismaterial", description = "Es gibt da eine dringende Angelegenheit, die Eurer Aufmerksamkeit bedarf, {name}.\n\nIn der Kanalisation wurde die Leiche einer Frau gefunden. Ein Messer steckte in ihrem Rücken.\n\nNormalerweise wäre solch ein Fund nicht weiter bemerkenswert... aber hierbei handelt es sich um keine einfache Halsabschneiderin. Sie gehörte zum SI:7!\n\nEinige unserer Leute bewachen den Leichnam, aber Ihr solltet Euch die Sache besser anschauen, bevor sie sich herumspricht.\n\nSollte der SI:7 davon erfahren... wäre das ziemlich schlecht für unsere Geschäfte.", sourceObjective = "Untersucht den Leichnam der SI:7-Agentin nach Spuren.", progress = "Habt Ihr den Leichnam identifiziert? War es eine Agentin des SI:7?", completion = "Es stimmt also? Eine Agentin des SI:7 wurde direkt vor unserer Nase ermordet?\n\nSollte SI:7 uns mit diesem Mord in Verbindung bringen, wäre das wirklich schlecht für unsere Geschäfte. Wir müssen dieser Sache auf den Grund gehen, und zwar lieber heute als morgen...", sourceObjectiveStatus = "unverified-source-field" }
quests[43959] = { id = 43959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erpressung von Haus Stelleris" }
quests[43960] = { id = 43960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cinderwing" }
quests[43961] = { id = 43961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestrix" }
quests[43962] = { id = 43962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingen des Schicksals", description = "Ich bin froh, dass die Waffe, die Ihr bei Euch führt, sich als nützlich erwiesen hat. Unser Verbündeter, der Lichkönig, hat angeboten, Euch einen Hinweis auf eine weitere Waffe zukommen zu lassen, wenn es Eurer aktuellen Waffe an etwas mangelt.\n\nDenkt genau über die Möglichkeiten nach und lasst mich wissen, nach welcher Ihr suchen wollt.", sourceObjective = "Wählt ein zweites Artefakt, das Ihr suchen wollt.", completion = "Nun gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[43963] = { id = 43963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vampiraten!" }
