quests[43968] = { id = 43968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinchshank" }
quests[43969] = { id = 43969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehilfe gesucht", description = "Ich mochte Margaux. Die Nachricht von ihrem Tod hat viele von uns tief getroffen.\n\n<Vanthir schüttelt traurig den Kopf.>\n\nWenn wir unser Werk fortsetzen wollen, müssen wir ein deutliches Signal senden. Leute von Durants Schlag sollen wissen, dass wir alles im Auge behalten und sie zur Rechenschaft ziehen.\n\nIch kenne jemanden, der uns dabei helfen könnte.\n\nEr heißt Arluin. Doch selbst wenn ich ihn als widerwilligen Verbündeten bezeichne, ist das noch großzügig. Er ist sehr vorsichtig und wird ohne Vergütung niemals sein Leben riskieren.\n\nIhr findet ihn in den Gassen nördlich des Immermondbasars.", sourceObjective = "Sucht Arluin und überzeugt ihn, Euch zu helfen.", progress = "Wenn Ihr keine Geschäfte im Sinn habt, solltet Ihr auch nicht hier herumlungern.", completion = "Ich werde Euch helfen, aber zunächst müsst Ihr etwas für mich tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[43970] = { id = 43970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewmaster Chosen" }
