quests[43972] = { id = 43972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistweaver Chosen" }
quests[43973] = { id = 43973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Pfade, zwei Waffen", description = "Wir haben die Schriftrollen durchforstet und neue Hinweise auf ein paar mächtige Waffen gefunden. Sie könnten sich für uns als nützlich erweisen.\n\nHier, lasst mich Euch zeigen, was ich gefunden habe. Wenn Euch etwas davon interessiert, dann lasst es mich wissen.", sourceObjective = "Wählt ein zweites Artefakt, das Ihr suchen wollt.", completion = "Eine weise Entscheidung.", sourceObjectiveStatus = "unverified-source-field" }
quests[43974] = { id = 43974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauhaus" }
quests[43975] = { id = 43975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung der Schildmaiden", description = "Die mächtige Val'kyr Savyn Ehrenstolz ist eingetroffen, um unsere Ränge zu verstärken. Sie bringt einige der tapfersten Schildmaiden der Vrykul in die Hallen der Tapferkeit.\n\nSprecht mit ihr und rekrutiert mächtige Truppen für unsere Armee.", sourceObjective = "Sprecht mit Savyn Ehrenstolz.", completion = "Ich werde in Odyns Namen die Würdigen zusammenrufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[43976] = { id = 43976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance Chosen" }
