quests[43979] = { id = 43979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resto Chosen" }
quests[43980] = { id = 43980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch eine alte Waffe", description = "Ihr habt Euch gut geschlagen, aber unsere Feinde sind mächtig und hinterlistig. Es wäre klug, auf alles vorbereitet zu sein, was sie auf uns loslassen.\n\nIhr wäret gut beraten, darüber nachzudenken, noch eine uralte Waffe zu besorgen, die uns in diesem Kampf weiterhelfen könnte.\n\nLasst mich wissen, wie Ihr verfahren wollt.", sourceObjective = "Wählt ein zweites Artefakt, das Ihr suchen wollt.", completion = "Eine gute Wahl.", sourceObjectiveStatus = "unverified-source-field" }
