quests[43984] = { id = 43984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant öffnet sich wieder", description = "Ihr habt Euch gut geschlagen, <Freund/Freundin>, aber Ihr wärt unaufhaltbar, wenn Ihr noch eine weitere Waffe hättet.\n\nHier, lasst mich Euch zeigen, welche Möglichkeiten uns noch bleiben. Wenn Euch eine davon interessiert, dann lasst es mich wissen.", sourceObjective = "Wählt ein zweites Artefakt, das Ihr suchen wollt.", completion = "Ja, sehr gute Wahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[43985] = { id = 43985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Gezeiten" }
