quests[43991] = { id = 43991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschützer", description = "Um die Kräfte des Götzen vollständig zu entfesseln, benötigen wir vier Manifestationen der Wildnis: eine Essenz der Wildheit, eine Essenz des Nachwachsens, eine Essenz des Gleichgewichts und eine Essenz der Hartnäckigkeit.\n\nUm diese Essenzen zu finden, müssen wir die Beschützer des Waldes konsultieren.\n\nBegebt Euch zum Smaragdgrünen Traumpfad und ruft die Mächte der uralten Druidensteine an. Die Beschützer werden sich nur jenen zeigen, die ihre Verbindung mit der Wildnis unter Beweis stellen können.", sourceObjective = "Verwendet Eure Druidenkräfte, um mit den Beschützern am Stein der Wildheit, am Wächterstein, am Stein der Wiederherstellung und am Stein des Gleichgewichts zu kommunizieren.", completion = "Habt Ihr die Beschützer der Wildnis spüren können? Sie sind immer bei uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[43992] = { id = 43992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgroth" }
