quests[43994] = { id = 43994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalyssra nähren", progress = "<Thalyssra zittert unkontrolliert und kann kaum sprechen.>", completion = "<Behutsam nimmt sie einen Kristall nach dem anderen aus Eurer Hand.>" }
quests[43995] = { id = 43995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valtrois nähren", progress = "<Valtrois reagiert nicht. Doch tief in ihr aufwallende Schmerzen stehen ihr ins Gesicht geschrieben.>", completion = "<Sie zögert einen Moment, bevor sie die Kristalle annimmt.>" }
