quests[44003] = { id = 44003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reef Lord Raj'his" }
quests[44004] = { id = 44004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringer des Lichts", description = "Turalyon lebt! Seit ewigen Zeiten war ich überzeugt, mein alter Freund hätte auf irgendeiner kargen Welt der Legion den Tod gefunden. Aber zu wissen, dass er noch lebt und sich in Gefahr befindet, ist einfach unerträglich.\n\nWir müssen uns beeilen, {name}. Wir müssen den heiligen Zweck des Objekts herausfinden.\n\nDer Prophet, von dem Turalyon gesprochen hat, ist zweifellos der Anführer der Draenei, Velen. Nehmt das Objekt und begebt Euch zur Exodar. Dort findet Ihr den Propheten Velen.\n\nIch werde nun ein Portal für Euch öffnen. Nehmt meinen Signalgeber und benutzt ihn, wenn Ihr zurückkehren wollt.", sourceObjective = "Findet den Zweck des mysteriösen lichtgebundenen Objekts heraus.", completion = "Kil'jaeden stahl das Kind von Velen und ließ Velen in dem Glauben, der Junge wäre tot. Dann hat er das Kind als Agenten der Brennende Legion aufgezogen, damit er seinen eigenen Vater ermordet? Dieser Bastard hat 13.000 Jahre auf seine Rache gewartet, nur weil Velen sich gegen Sargeras und die Legion gestellt hat? Der Betrüger... ein wahres Wort...\n\nDass Velen nach allem, was ihm und seinem Volk widerfahren ist, solch eine Tragödie erleiden musste... Es bricht mir das Herz. Ein solches Schicksal stellt auch den stärksten Glauben auf eine harte Probe.", sourceObjectiveStatus = "unverified-source-field" }
quests[44005] = { id = 44005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Reaction to Warrior Artifacts" }
quests[44006] = { id = 44006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer volles Potenzial", description = "Ich sehe, dass Ihr viele Pfade beschreitet, wie es wahre Schamanen tun sollten.\n\nEs sind bereits zwei mächtige Artefakte in Eurem Besitz. Ein drittes zu suchen, wäre keine Gier: Es würde Euer Schicksal erfüllen... die Vollendung eines Kreises.\n\nSprecht mit mir. Gemeinsam werden wir Euer volles Potenzial erschließen.", sourceObjective = "Sprecht mit Aggra, um ein drittes Artefakt auszuwählen, nach dem Ihr suchen wollt.", completion = "Der Pfad, der vor Euch liegt, ist klar. Eure Verbündeten erwarten Euch auf diesem Vorsprung. Mögen die Geister über Euch wachen, Scharfseher!", sourceObjectiveStatus = "unverified-source-field" }
quests[44009] = { id = 44009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sternschnuppe", description = "Danke, dass Ihr gekommen seid, {class}t {name}. Es gibt da eine dringende Angelegenheit, die Eurer speziellen Talente bedarf.\n\nDer Orden der Silbernen Hand hat gemeldet, dass ein außergewöhnlich leuchtendes Objekt aus dem Teufelssturm aufgetaucht ist und im Moment auf die Küste von Suramar herabstürzt. Am meisten hat mich bei dem Bericht verblüfft, dass dieses Objekt \"eine Schneise durch den Teufelssturm\" selbst geschnitten hat.\n\nWürdet Ihr Euch das bitte ansehen? Ein Greif erwartet Euch bereits an Krasus' Landeplatz.", sourceObjective = "Findet das mysteriöse lichtgebundene Objekt.", progress = "Zeigt mir, was Ihr gefunden habt.", completion = "Äußerst merkwürdig, in der Tat! Dieses Objekt hat auf keinen Fall die Legion gefertigt. Das muss ich mir näher ansehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44010] = { id = 44010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Oreth der Grässliche" }
