quests[44033] = { id = 44033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Nüsse" }
quests[44034] = { id = 44034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch eine würdige Klinge", description = "Wir haben immer noch einige Pläne, um andere unglaublich mächtige Waffen zu besorgen, die Euch in Zukunft vielleicht noch gute Dienste leisten werden.\n\nGern gehe ich mit Euch die verschiedenen Optionen durch, damit Ihr die richtige Entscheidung treffen könnt.", sourceObjective = "Wählt ein zweites Artefakt, das Ihr suchen wollt.", completion = "Ja, ich denke, das ist eine gute Wahl.\n\nEine wirklich gute Wahl.", sourceObjectiveStatus = "unverified-source-field" }
