quests[44037] = { id = 44037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Chosen" }
quests[44038] = { id = 44038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subtlety Chosen" }
quests[44039] = { id = 44039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea King Tidross" }
quests[44040] = { id = 44040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Vertrauensvotum", description = "Ich werde meinen Sohn bis nach der Abstimmung so gut wie möglich schützen.\n\nCoryn Stelleris gilt selbst unter den Adeligen als Raubtier. Es überrascht mich nicht, dass er zu solch üblen Mitteln greift, um seinen Erfolg zu sichern.\n\nSagt Ly'leth, dass ich sie unterstütze. Ohne Vorbehalt.\n\nIhr könntet ihr auch sagen, dass Coryn Stelleris sie verletzen wird, wenn sie ihm dazu Gelegenheit gibt.\n\nSeid vorsichtig.", sourceObjective = "Kehrt zu Ly'leth beim Mondsichelforum zurück.", completion = "Ich weiß über Coryn Bescheid und versichere Euch, wir werden das Gift dieser Natter nicht unterschätzen.\n\nVielen Dank, dass Ihr Aurore geholfen habt. Sie ist mir lieb und teuer.", sourceObjectiveStatus = "unverified-source-field" }
quests[44041] = { id = 44041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die blutige Wahrheit", description = "Wir müssen herausfinden, wer hinter dem Anschlag auf Amber Kearnen steckt.\n\nEs wird nicht lange dauern, bis der SI:7 bemerkt, dass eine ihrer Agentinnen vermisst wird, und dann anfängt, in der Halle der Schatten herumzuschnüffeln.\n\nHier, nehmt diese elegante Ermittlerbrille, um nach Spuren von Hämoglobin zu suchen. Ich war so frei, sie speziell auf Amber Kearnens Blut einzustellen.\n\nFolgt der Blutspur, um die Schuldigen zu finden, aber gebt Euch nicht zu erkennen!\n\nErstattet uns Bericht, wenn Ihr die benötigten Informationen habt.", sourceObjective = "Deckt die Wahrheit hinter dem Anschlag auf die SI:7-Agentin auf.", completion = "Noch mal in aller Deutlichkeit...\n\nIhr sagt, dass Meister Mathias Shaw den Tod einer seiner besten Agentinnen angeordnet hat? Das ist noch ernster, als ich dachte.\n\nWir müssen weiter nach Hinweisen suchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[44043] = { id = 44043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende geht weiter", description = "Es gibt immer noch zwei Pfade, auf denen Ihr wandeln könnt. Zwei mächtige Waffen, die Ihr für Euch sichern und gegen die Legion in die Schlacht führen könnt.\n\nIch werde Euch natürlich helfen, die verbleibenden Optionen zu beurteilen.", sourceObjective = "Wählt ein zweites Artefakt, das Ihr suchen wollt.", completion = "Ihr habt Euch für einen weisen Pfad entschieden. Möge er Euch bis an Euer Ziel führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44044] = { id = 44044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Experimente" }
