quests[44049] = { id = 44049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Böse hat viele Beine" }
quests[44050] = { id = 44050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dämonenpakt muss fallen" }
quests[44051] = { id = 44051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschwendetes Potenzial", description = "Ihr habt viel für uns getan, doch es ist an der Zeit, dass Ihr zu Thalyssra zurückkehrt.\n\nGanz in der Nähe befindet sich eine Teleportationsplattform, die seit einigen Jahren nicht mehr verwendet wird. Versucht doch, ob ihr sie umlenken und so zu Thalyssra zurückkehren könnt.\n\nUnd bevor Ihr Euch auf den Weg macht:\n\n<Vanthir überreicht Euch eine verpackte Flasche Arkwein.>\n\nBringt ihr den mit meinem Dank dafür, dass sie Euch hergeschickt hat. Lasst sie wissen, dass wir dank Eurer Mühen wieder einen Vorrat an Arkwein haben und eine Mutter mit ihrem Kind wiedervereint wurde.\n\nWir sind Euch unendlich dankbar. Lebt wohl.", sourceObjective = "Aktiviert die Teleportationsplattform und überbringt Thalyssra Vanthirs Geschenk.", completion = "Es gibt Gerüchte, Ihr wolltet die Stadt verlassen... und dass es noch einen Ort für die Nachtgeborenen gibt, wo man uns nicht für Elisandes Wahnsinn verantwortlich macht.\n\nIch würde Euch gern begleiten.\n\nMeine Harfe und meine Hände sind hier unerwünscht. Sie gehören Euch.\n\nIhr müsst es nur sagen, und ich begleite Euch durch den Teleporter und teile meine Musik mit allen, die mich auf der anderen Seite erwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[44052] = { id = 44052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und sie werden erzittern", description = "Die Ereignisse des heutigen Tages werden Konsequenzen nach sich ziehen.\n\nFür den Moment solltet Ihr zu Thalyssra zurückkehren. Sagt ihr, Margaux ist gerächt und dass die Dämmerlilie sich ganz Suramar offenbart hat.\n\nNoch viele werden den Tod finden, bevor dieser Krieg zu Ende geht, aber eins ist sicher: Nach diesem Tod wissen alle von Durants Schlag, dass sie sich in Zukunft vorsehen müssen.", sourceObjective = "Kehrt zu Thalyssra zurück.", completion = "Was für eine Erleichterung, wenn auch nur eine kleine. Ihr habt Euch gut geschlagen. Ruht Euch aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[44053] = { id = 44053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde mit gewissen Vorzügen", description = "Der Diener der Lunastres, stumm wie immer, übergibt Euch eine mit Wachs versiegelte Schriftrolle.\n\nDarin steht:\n\"<Werter/Werte> {name},\n\nich habe meinen Diener gebeten, Euch abzufangen, wenn alles zu meinen Gunsten läuft.\n\nAls Beraterin werde ich wohl die nächste Zeit nicht zum Anwesen zurückkehren und habe daher ein Geschenk für Thalyssra ausgewählt.\n\nEinige meiner Diener sind mit besonderen Gegenständen auf dem Weg nach Shal'Aran. Behandelt sie gut. Sie brauchen jemanden, dem sie dienen können, und ich könnte mir niemanden vorstellen, der besser geeignet wäre!\n\nRichtet den anderen meinen Dank und meine Liebe aus.\nBeraterin Ly'leth Lunastre\"", sourceObjective = "Kehrt zu Thalyssra zurück.", completion = "Sie ist zweifellos eine würdige Gefährtin.", sourceObjectiveStatus = "unverified-source-field" }
quests[44054] = { id = 44054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonizid" }
quests[44055] = { id = 44055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben einen Grubenlord", description = "Die Teufelstotems sind nicht die Ersten, die den Verlockungen der Legion erlegen sind. Und sie werden auch nicht die Letzten bleiben.\n\nAber in ihrer Arroganz haben sie nun einen Grubenlord beschworen.\n\nWerdet Ihr uns in der Schlacht gegen diese Bestie beistehen? Die Macht Eures Artefakts und Eure Fähigkeiten wären gegen diese Kreatur von unschätzbarem Wert.", sourceObjective = "Bezwingt Kuglaroth.", completion = "Mit den anderen Dämonen werden wir im Laufe der Zeit schon fertig. Aber dieser Grubenlord... Eine solche Ausgeburt des Bösen hätten wir alleine niemals besiegt. Ihr wart wirklich eine große Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[44057] = { id = 44057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein \"nobles\" Ereignis", description = "Die Einladung scheint für eine exklusive Fuchsjagd zu sein. Sie wollen irgendwo auf den Verheerten Inseln einen seltenen und scheuen Fuchs namens Volpin jagen. Vielleicht können wir das zu unserem Vorteil nutzen?\n\nWir müssen mehr Informationen über die Jagd erlangen, aber wir sollten dabei die Nachtgeborenen nicht auf unsere Pläne aufmerksam machen. Eure Champions können das für Euch übernehmen und herausfinden, wo die Jagd stattfinden wird.", sourceObjective = "Entsendet Eure Champions, um etwas über die Jagd herauszufinden.", progress = "Haben Eure Champions etwas über die Fuchsjagd herausgefunden?", completion = "Ja, es ist alles hier, der Ort der Jagd auf Volpin.\n\nIch bin mir sicher, dass es für eine solch wunderbare Kreatur eine bessere Verwendung denn als Pelzschmuck auf den Schultern eines Adligen gibt, findet Ihr nicht auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[44058] = { id = 44058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der scheue Volpin", description = "Laut dieser Karte soll die Fuchsjagd im Jagdrevier der Federmähnen in Suramar beginnen. Sollten sie Erfolg haben, würden die Nachtgeborenen Volpin als letzten Fuchs seiner Art auf den Verheerten Inseln töten.\n\nReist in das Jagdrevier und verhindert diese Jagd.", sourceObjective = "Verhindert die Fuchsjagd.", sourceObjectiveStatus = "unverified-source-field" }
quests[44059] = { id = 44059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion Attacks" }
