quests[44062] = { id = 44062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suramar Teleport Learned" }
quests[44063] = { id = 44063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung für Euer Arsenal", description = "Hochlord, es gibt immer noch einige Waffen, die Ihr Euch für den Kampf gegen die Legion sichern könnt. Während Ihr auf den Verheerten Inseln wart, haben wir sie nicht aus den Augen gelassen.\n\nEs wäre mir eine Ehre, alle Optionen mit Euch durchzugehen.", sourceObjective = "Wählt ein zweites Artefakt, das Ihr suchen wollt.", completion = "Ausgezeichnet. Wir haben keine Zeit zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[44064] = { id = 44064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy Chosen" }
