quests[44073] = { id = 44073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe von innen" }
quests[44074] = { id = 44074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: Essenz der Hartnäckigkeit", description = "Ich grüße Euch, <Erzdruide/Erzdruidin>. Ich hörte, dass Ihr auf der Suche nach der Essenz der Hartnäckigkeit seid.\n\nEs gibt nichts Robusteres und Unzerbrechlicheres als eine Kreatur aus Stein.\n\nIn Neltharions Hort gibt es ein Monster namens Rokmora. Tötet es und entzieht ihm die Essenz, die Ihr benötigt.", sourceObjective = "Beschafft 1 Essenz der Hartnäckigkeit von Rokmora in Neltharions Hort und tötet dann Dargrul den Unterkönig.", progress = "Bleibt standhaft, {class}.", completion = "Habt Dank, Erzdruide.", sourceObjectiveStatus = "unverified-source-field" }
quests[44075] = { id = 44075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Essenz der Wildheit", description = "Um die Essenz der Wildheit zu finden, müsst Ihr eine Kreatur aufsuchen, die schon Tausende getötet hat und selbst von den Göttern verehrt wird.\n\nIch spreche von niemand Geringerem als dem Wolf Fenryr, der in den ewigen Wäldern der Hallen der Tapferkeit jagt.", sourceObjective = "Beschafft 1 Essenz der Wildheit von Fenryr in den Hallen der Tapferkeit und beweist danach Odyn, dass Ihr würdig seid.", progress = "Es braucht eine wilde Bestie, um eine wilde Bestie zur Strecke zu bringen.", completion = "Ausgezeichnet, Erzdruide.", sourceObjectiveStatus = "unverified-source-field" }
quests[44076] = { id = 44076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Essenz des Nachwachsens", description = "Mein Kind, ich kann mir nur einen Ort vorstellen, an dem man die Essenz des Nachwachsens bekommen könnte.\n\nTief im Finsterherzdickicht befindet sich Eichenherz, ein treuer, uralter Verteidiger des Hains. Er ist kürzlich der Verderbnis des Alptraums anheimgefallen, aber tief im Innern seines Herzens kämpft er noch dagegen an.\n\nBeschafft die Essenz dieses großen Baumes, damit seine unsterbliche Seele zur Schaffung neuen Lebens verwendet werden kann.", sourceObjective = "Beschafft 1 Essenz des Nachwachsens von Eichenherz im Finsterherzdickicht und besiegt dann den Schemen von Xavius.", progress = "Mein Herz blutet für alle, die Opfer des Alptraums geworden sind.", completion = "Die Nachricht von Eichenherz' Tod stimmt mich traurig, aber seine Seele wird weiterleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[44077] = { id = 44077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Essenz des Gleichgewichts", description = "Im Auge Azsharas in Azsuna gibt es ein mächtiges Wesen namens Azsharas Zorn. Es ist eine Blasphemie der Natur, durchdrungen mit gestohlener arkaner Macht, deren Existenz wir nicht zulassen dürfen.\n\nTötet es. Vielleicht findet Ihr so die Essenz des Gleichgewichts, nach der Ihr sucht.", sourceObjective = "Beschafft 1 Essenz des Gleichgewichts von Azsharas Zorn.", progress = "Wir folgen Elunes Pfad.", completion = "Wunderbar. Das ist genau, was wir brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44078] = { id = 44078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützendes Wirken" }
quests[44079] = { id = 44079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druids of the Scythe - 1" }
quests[44080] = { id = 44080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund der Tiere" }
quests[44081] = { id = 44081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treacherous Leyrunners" }
quests[44082] = { id = 44082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritter der Schwarzen Klinge", description = "Korgaz Totaxt ist in Acherus eingetroffen, um uns beim Rekrutieren weiterer Todesritter zu unterstützen. Er hat ein gutes Auge für ihr Potenzial.\n\nIch kann nicht oft genug betonen, dass es äußerst wichtig ist, unsere Reihen im Kampf gegen die Brennende Legion immer wieder aufzufüllen.\n\nDie Zahl der Dämonen ist nahezu endlos und wir sind nur wenige.\n\nSprecht mit Korgaz, wenn Ihr bereit seid, weitere Todesritter zu rekrutieren.", sourceObjective = "Sprecht mit Korgaz Totaxt.", completion = "Ich grüße Euch, Todesgebieter. Es ist mir eine Ehre, Euch zu dienen.\n\nIch habe die Verluste von Allianz und Horde auf dem Schlachtfeld im Auge behalten. Das Angebot ist begrenzt, aber es gibt ein paar vielversprechende Nachwuchskräfte...", sourceObjectiveStatus = "unverified-source-field" }
quests[44083] = { id = 44083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grimoire des ersten Nekrolythen", description = "Dieser uralte Foliant scheint das Zauberbuch von Sataiel zu sein, der ersten Nekrolythin.\n\nZwischen all den Seiten voller Flüche und Zaubersprüche entdeckt Ihr die Anleitungen für ein Ritual, mit dem Sataiel Ulthalesh, der Sense der Totenwinde, neue Macht verleihen wollte. Sie nannte dieses Ritual \"Ritus des Scharfrichters\".\n\nSie hatte zwar den Ort schon ausgewählt und alle Vorbereitungen getroffen, aber sie starb, bevor sie ihr Werk vollenden konnte. Vielleicht gelingt es Euch, dort anzusetzen, wo sie aufhören musste?\n\nAls Erstes benötigt Ihr ein paar Schädel.", sourceObjective = "Sammelt 13 Schädel der Hingerichteten von mächtigen humanoiden Champions auf den Verheerten Inseln und bringt sie zum Altar des Scharfrichters in der Gruft bei Morgans Grund am Gebirgspass der Totenwinde.", progress = "Auf dem Altar ist gerade genug Platz für all die Schädel, die Ihr gefunden habt.", completion = "Der Altar ist vom Staub der Jahrhunderte bedeckt, aber dennoch sieht man den Kerzenschein schon aus der Ferne.\n\nDas muss der Ort des Rituals sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[44084] = { id = 44084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für Margaux", description = "<Sylverin ist leichenblass und schäumt vor Wut.>\n\nWie können sie es wagen? Margaux hat alles getan, was sie ihr aufgetragen haben und noch mehr! Der Arkwein ist nie versiegt, trotz allem, was sie uns angetan haben! Und ihr!\n\nSolch ein Unrecht darf nicht ungesühnt bleiben. Wir müssen Margaux rächen.", sourceObjective = "Tötet 8 Weingutvollstrecker oder Weingutaufseher.", completion = "<Thalyssra ist einen kurzen Augenblick lang sprachlos.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44085] = { id = 44085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Affliction Chosen" }
quests[44086] = { id = 44086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destruction Chosen" }
quests[44087] = { id = 44087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zur Teufelshammer zurück.", description = "{name}, Schlachtenfürst Gaardoun hat mich angewiesen, nach Euch zu suchen. Er sagte, er bräuchte Eure Hilfe in einer sehr wichtigen Angelegenheit.\n\nEr möchte, dass Ihr so schnell wie möglich auf die Teufelshammer kommt.", sourceObjective = "Sprecht mit Schlachtenfürst Gaardoun auf der Teufelshammer.", completion = "Kommandant, ich bin froh, dass Asha Euch so schnell ausfindig machen konnte.\n\nEs gibt eine Sache, um die Ihr Euch so schnell wie möglich kümmern müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[44088] = { id = 44088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonology Chosen" }
quests[44089] = { id = 44089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein größeres Arsenal", description = "Der Foliant sagt, es gibt noch eine letzte Waffe, die <Freund/Freundin> gegen unsere Feinde einsetzen kann.\n\nWollt Ihr sie suchen?", sourceObjective = "Sprecht mit Calydus, um die Suche nach dem letzten Artefakt zu beschließen.", completion = "Freund sehr weise! Man kann nie genug Waffen haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[44090] = { id = 44090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwur der Treue", description = "Der Adler scheint eine Nachricht für Euch zu haben:\n\n\n\nIch hoffe, Ihr seid wohlauf.\n\nDie Kunde von Ohn'ahras Omen hat sich schnell herumgesprochen. Viele möchten <dem neuen Anführer/der neuen Anführerin> des Unsichtbaren Pfads die Treue schwören.\n\nKehrt zu mir in die Volltrefferhütte zurück, damit wir das besprechen können.\n\n- Altarhüter Biehn", sourceObjective = "Kehrt zu Altarhüter Biehn in der Volltrefferhütte zurück.", completion = "Wie ich sehe, habt Ihr meine Nachricht erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[44092] = { id = 44092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schutz der heimischen Front", description = "Die Legion ist nicht nur in diese Stadt gedrungen. Das von ihr ausgehende Böse verbreitet sich über ganz Azeroth und bedroht die äußersten Randbereiche unserer Welt.\n\nWir müssen sie finden und aufhalten, wo auch immer ihre Dunkelheit Fuß fasst.\n\nWir haben Späher ausgesandt, die sich auf der ganzen Welt nach Legionsaktivität umsehen. Sobald Invasionen starten, werden wir die Standorte auf Eurer Karte markieren.\n\nLasst sie leiden, {name}!", sourceObjective = "Öffnet Eure Karte, um aktive Legionsinvasionen in Kalimdor oder den Östlichen Königreichen zu finden. Geht zum Invasionsort und haltet die Dämonen auf!", completion = "Ihr habt es geschafft! Ihr habt eine Invasion gebrochen!\n\nWenn das nur das Ende unseres Kampfes wäre. Doch die Legion gibt erst nach, wenn sie vernichtet wurde... oder uns vernichtet hat.\n\nGebt nicht auf! Schlagt mehr dieser elenden Invasionen zurück, {name}. Die Wyrmzunge, die wir hier gefangen halten, wird Eure Bemühungen entlohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44093] = { id = 44093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head 1 Looted" }
quests[44094] = { id = 44094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head 2 Looted" }
quests[44095] = { id = 44095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head 3 Looted" }
