quests[44097] = { id = 44097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head 5 Looted" }
quests[44098] = { id = 44098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung von Lehrlingen", description = "Die Großbeschwörerin Mimik ist eingetroffen, um unsere Ränge zu verstärken. Sie findet stets die aussichtsreichsten Lehrlinge und bildet sie sehr schnell aus. Ihre früheren Schüler zählen zu den mächtigsten Beschwörern im ganzen Land!\n\nSprecht mit ihr und rekrutiert einige ihrer Lehrlinge für unsere Armee.", sourceObjective = "Sprecht mit Großbeschwörerin Mimik.", completion = "Schön, Euch zu sehen, {name}. Meine Lehrlinge lernen schnell und sind bereit, Euch zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44099] = { id = 44099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gemeinsamer Freund", description = "Es freut mich, dass Ihr wohlauf seid.\n\nUnser gemeinsamer Freund Calydus hat mich geschickt. Er möchte Euch unbedingt sprechen.\n\nBitte kehrt so bald wie möglich zur Schreckensnarbe zurück.", sourceObjective = "Kehrt zu Calydus in der Schreckensnarbe zurück.", completion = "Es ist so schön, Freund wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44100] = { id = 44100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordnungsgemäße Vorstellung", description = "Gut, dass ich Euch gefunden habe.\n\nIch habe eine Nachricht von Alonsus Faol.\n\nEr sagt, dass es an der Zeit ist, sich vorzustellen, und bittet Euch, so bald wie möglich zum Netherlichttempel zu kommen.", sourceObjective = "Kehrt zu Alonsus Faol im Netherlichttempel zurück.", completion = "Wie ich sehe, habt Ihr meine Nachricht erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[44101] = { id = 44101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte abgeliefert", description = "Diese Vorräte für den Irdenen Ring sind noch unverarbeitet. Jemand hat wohl alles durchwühlt und mitgenommen, was er tragen konnte. Angesichts des Champions der Grimmtotems, der gleich da vorn ganz unverblümt Eure Sachen durchforstet, fällt Euer Verdacht direkt auf seinen Stamm.\n\nFordert den Grimmtotem heraus, um Eure Ressourcen zu sichern!", sourceObjective = "Fordert den Champion der Grimmtotems heraus, der Eure Vorräte plündert, und besiegt ihn.", progress = "<Der Champion der Grimmtotems schnaubt Euch verächtlich an.>", completion = "Also gut, ich gebe auf, ich gebe auf!\n\nSeid verflucht, {class}, und auch Eure Waffe. Ohne sie hättet Ihr die Grimmtotems niemals besiegt.\n\nNehmt Eure lausigen Vorräte. Wir sehen uns wieder!", sourceObjectiveStatus = "unverified-source-field" }
quests[44102] = { id = 44102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 043 - Grey Shoals" }
quests[44103] = { id = 44103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 044 - Felblaze Underwater" }
quests[44104] = { id = 44104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 045 - Ley Ruins 02" }
quests[44105] = { id = 44105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 046 - Temple of a Thousand Lights" }
quests[44106] = { id = 44106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide der Lehren", description = "Elothir lebt im Einklang mit der Natur im uralten Hain Thas'talah und unterrichtet seine Akolythen in den Künsten des Heilens und im Bewahren der Lehren.\n\nSucht ihn auf und teilt ihm mit, dass er hier dringend benötigt wird.", sourceObjective = "Sucht Elothir in Thas'talah auf.", completion = "Willkommen, {name}. Die Nachricht von Euren Heldentaten hat sich bereits vom Hain der Träume bis zu uns herumgesprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44108] = { id = 44108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ragemaw" }
quests[44112] = { id = 44112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handel mit Träumen", description = "Eurem Aussehen nach zu urteilen, seid Ihr <ein Alchemist/eine Alchemistin>, nicht wahr?\n\nIch wäre bereit, Euch meine Dienste für einen Preis anzubieten, den ich für angemessen erachte.\n\nIch war schon lange nicht mehr in Suramar. Mich dürstet es nach Yseras Traumtrank. Gebraut wird er aus Traumlaub und den Blättern einer Träumerträne.\n\nEine von ihnen steht nicht weit von hier auf der Lichtung bei den Ruinen. Nehmt mein Fläschchen, braut den Trank für mich und ich werde Euch helfen.", sourceObjective = "Benutzt das Fläschchen der Nachtgeborenen, um Yseras Traumtrank herzustellen.", progress = "<Leyweberin Erenyi scheint in Gedanken versunken zu sein.>", completion = "Das ist Euch ganz gut gelungen. Ich bin ein bisschen beeindruckt.\n\nNun lasst mich mal Eure Seide ansehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[44113] = { id = 44113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Achronos" }
quests[44114] = { id = 44114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Magistrix Vilessa" }
quests[44115] = { id = 44115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen bei Legion!", description = "Willkommen bei World of Warcraft: Legion! Wir hoffen, dass Euch all die neuen Erfahrungen gefallen, die rund um die Verheerten Inseln auf Euch warten. Eins noch: Bewaffnet Euch bis an die Zähne, bevor Ihr Euch mit der Brennenden Legion anlegt." }
quests[44116] = { id = 44116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis der Citrinbucht", description = "Die Brennende Legion marschiert in Azeroth ein, und SI:7 verschwendet wertvolle Ressourcen, um eine ihrer besten Agentinnen zu jagen und zu ermorden?\n\nEtwas stimmt hier nicht...\n\nWir müssen herausfinden, wie tief dieses Komplott reicht. Warum wurde Amber Kearnen von ihrer eigenen Organisation gejagt?\n\nVielleicht findet sich in dem verschlüsselten Brief, den sie bei sich trug, ein Hinweis. Wir brauchen mehr Informationen.\n\nDie Assassinen des SI:7, die Ihr in Dalaran verfolgt habt, erwähnten die Citrinbucht... Sucht in der Citrinbucht nach Hinweisen. Wir kümmern uns um die Entschlüsselung dieses Briefes.", sourceObjective = "Sprecht mit Flottenadmiral Tethys in der Citrinbucht von Sturmheim.", completion = "Jetzt stoßt mal nicht so ins Horn... Da vorn sind Piraten! Und das sind keine Seebären, von denen Ihr Euch beißen lassen wollt...", sourceObjectiveStatus = "unverified-source-field" }
quests[44117] = { id = 44117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie die Zeit verfliegt, wenn man Rum hat!", description = "Es gibt nur wenige Piraten, die Euch so schnell auf den Meeresgrund schicken wie die Roten Säbel! Ein echter Haufen Haudegen!\n\nAber... vom Rum verstehen sie was! Ich will ehrlich sein, {name}... Nur wenig Rum hat so viel Bumms wie der von des Roten Säbels!\n\nDa Ihr ja eh schon alles nach Hinweisen auf den Kopf stellt, bringt doch gleich auch ein paar Fläschchen mit!\n\nBesorgt mir so viele Flaschen, wie Ihr könnt, und ich gebe Euch eine fette Belohnung! Bei meiner Piratenehre, {name}!", sourceObjective = "Sammelt 10 Flaschen Rum des Roten Säbels.", progress = "Habt Ihr den Gewürzrum, {name}?", completion = "<Flottenadmiral Tethys entkorkt eine Flasche und nimmt einen tiefen Zug.>\n\nHa, das gibt Haare auf der Brust, {name}. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[44118] = { id = 44118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Auditor Esiel" }
quests[44119] = { id = 44119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Volshax der Willensbrecher" }
quests[44120] = { id = 44120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündete der Illidari", description = "Zunächst war ich unsicher, ob wir die Illidari in die Stadt lassen sollten. Aber sie könnten tatsächlich unser aller Leben gerettet haben.\n\nIch habe den Dämonenjägern erlaubt, ein Übergangslager im Magierviertel einzurichten. Ich möchte, dass Ihr sie als <mein persönlicher Abgesandter/meine persönliche Abgesandte> besucht. Dankt den Illidari für ihre Hilfe und findet heraus, wie sie unsere Sache unterstützen können.\n\nIhr... Ihr müsst einfach nur die Augen aufhalten. Sie haben eine furchtbare Macht gebändigt, und wir müssen vorbereitet sein, sollten sie eines Tages Opfer ihrer inneren Dunkelheit werden.", sourceObjective = "Trefft Euch mit dem Repräsentanten der Illidari im Magierviertel von Sturmwind.", completion = "Die Blutspritzer zeigen mir, dass Jace Euch die Dämonen gezeigt hat. Dem jungen König geht es hoffentlich gut.\n\nWir haben noch immer zu tun, {class}. Noch eine ganze Menge.", sourceObjectiveStatus = "unverified-source-field" }
quests[44121] = { id = 44121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Az'jatar" }
