quests[44136] = { id = 44136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 056 - The Undergorge - zto" }
quests[44137] = { id = 44137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Getümmel", description = "Die Brennende Legion hat hier einen Sieg errungen, aber die Illidari auch. Anscheinend können die Dämonenjäger dem Ansturm standhalten... wenn auch nur mit Müh und Not.\n\nKommt, setzen wir Eure Waffe sinnvoll ein. Ich werde unsere nächsten Schritte planen, während Ihr die Legion niederkämpft.", sourceObjective = "Sprecht mit dem kommandierenden Dämonenjäger am Verteidigungsposten der Illidari.", completion = "Ihr seid ein wahrhaft willkommener Anblick, {name}. Und mit Erzmagier Khadgar steht Euch beträchtliche Feuerkraft zur Seite.\n\nMalicia hat uns immer wieder durch die Portale gejagt, von hier zur Teufelshammer und zurück. Wir konnten die Dämonen zwar aus diesen Ruinen vertreiben, aber sie sind stärker als alle, denen wir zuvor begegnet sind.\n\nWir wissen Eure Führung sehr zu würdigen. Wenn wir die Invasion der Legion jetzt nicht aufhalten können, werden sie erst Azsuna und dann den Rest der Verheerten Inseln überrennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44138] = { id = 44138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 057 - Kel'delar - ZTO" }
quests[44139] = { id = 44139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 058 - Dreadroot - zto" }
quests[44140] = { id = 44140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von innen heraus", description = "Unsere Dämonenjäger, Kor'vas Blutdorn und Cyana Nachtgleve, sind mit einer kleinen Streitmacht der Illidari nach Faronaar übergesetzt. Ihre Mission war es, die Legion von innen heraus zu schwächen.\n\nIch habe schon eine Weile nichts von ihnen gehört.\n\nEs wäre das Beste, wenn Ihr sie finden und zum Erfolg führen könntet. Einverstanden?", sourceObjective = "Sucht nach Kor'vas Blutdorn auf Faronaar am Triumphposten.", completion = "Oh, Ihr seid es, {name}. Gut, wir haben hier nämlich ein kleines Problem.\n\nTraut Kain Cyana und mir nicht zu, damit fertigzuwerden? Vielleicht hat er dieses Mal recht.", sourceObjectiveStatus = "unverified-source-field" }
quests[44141] = { id = 44141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
