quests[44151] = { id = 44151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[44152] = { id = 44152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ausufernde Krise", description = "Der Arcan'dor schwindet.\n\nDiese Energie war einst in seinem Geäst gebunden und trieb sein Wachstum voran. Es existierte ein Gleichgewicht zwischen dem Leben und dem Arkanen.\n\nJetzt bahnt die Energie sich einen Weg nach draußen. Wenn sein Herz sie nicht länger halten kann, wird dieser Baum jedes Lebewesen in dieser Halle töten.\n\nIch habe so etwas bereits früher einmal erlebt und muss einen Weg finden, zu verhindern, dass es wieder geschieht.\n\nWir müssen zu dem Baum gehen, der vor ihm da war. Seine Überreste können uns den Weg weisen.\n\nTrefft mich beim Tempel von Fal'adora. Wir werden gemeinsam hinabsteigen.", sourceObjective = "Trefft Talwandler Farodin am Tempel von Fal'adora. Um dorthinzugelangen, könnt Ihr das Portal nach Falanaar in Shal'Aran verwenden.", completion = "Ich muss einen Weg finden...", sourceObjectiveStatus = "unverified-source-field" }
quests[44153] = { id = 44153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bürde des Lichts", description = "\"Ihr habt nicht um diese Bürde gebeten, aber das Schicksal hat es so gewollt.\" Turalyons düstere letzte Worte klingen mir immer noch in den Ohren. Ich fürchte um die Draenei... und um meinen Freund Velen. Aber wir müssen stark bleiben, {name}!\n\nFür den Moment verbleibt das Herz des Lichts unter Euren wachsamen Augen. Es gibt einen Ort auf Azeroth, dem ich die Sicherheit dieses Objekts anvertrauen würde: Eure Ordenshalle. Bringt es dorthin, {name}. Ich bleibe in Dalaran und suche weiter nach Antworten. Es muss einen anderen Weg geben!", sourceObjective = "Platziert das Herz des Lichts in Eurer Ordenshalle.", progress = "Hier müsst Ihr das Herz des Lichts ablegen.", completion = "<Eine Macht erwacht im Herz des Lichts, als Ihr es ablegt.>\n\n<Ihr verspürt neue Hoffnung.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44154] = { id = 44154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ritus des Scharfrichters", description = "Die Schädel sind gesammelt und der Ort für das Ritual ist vorbereitet.\n\nJetzt fehlen nur noch die Worte des Zaubers, und Ulthalesh wird mit der Essenz des Scharfrichters erfüllt.", sourceObjective = "Interagiert mit dem Schädelhaufen und schließt den Ritus des Scharfrichters in der Gruft nahe Morgans Grund am Gebirgspass der Totenwinde ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[44155] = { id = 44155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise suchen", description = "Es ist kein Zufall, dass wir hier in der Citrinbucht 'nen Mord aufklären wollen und dabei über die elenden Piraten der Roten Klinge stolpern!\n\nEindeutig kein Zufall, bei meinen Wanten. Aber wir brauchen Beweise, {name}!\n\nIhr sucht nach Spuren und ich schnappe mir 'n paar Landratten, die ich kielholen kann.\n\nHa, {name}. Wir zwei schaffen das schon. Mast- und Schotbruch!", sourceObjective = "Findet den Beweis, dass der SI:7 mit dem Roten Säbel unter einer Decke steckt.", progress = "Habt Ihr einen Beweis, dass die elenden Piraten des Roten Säbels hinter dem Mord stecken?", completion = "Ha, was haben wir denn da? Ein Brief von Meister Mathias Shaw persönlich! Und dann noch an den Roten Säbel.\n\nIch wusste es doch... Diese Befehle stinken noch mehr zum Himmel als 'n Fass Köder.", sourceObjectiveStatus = "unverified-source-field" }
